'use strict';

function createContext(options) {
  return {
    options,
    shouldFix: !!options['fix'],       // gates OpenRewrite only
    shouldReport: !!options['report'],
    target: null,
    project: {
      isNode: false, isJava: false,
      major: null,
      cdsDepName: null,
      packageJsonFiles: [],
      pomXmlFiles: [],
      projectTypeMessage: null,
    },
    proposal: { updates: [], removals: [] },
    verifyMismatches: [],
    rewriteRan: false,
    installRan: false,
  };
}

module.exports = { createContext };
